node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search reminders for ORD-12AAA3
const reminders = db.prepare(\"SELECT * FROM ts_reminders WHERE content LIKE '%ORD-12AAA3%'\").all();
console.log('Reminders matching ORD-12AAA3:', JSON.stringify(reminders, null, 2));

// Also check messages
const msgs = db.prepare(\"SELECT * FROM ts_messages WHERE content LIKE '%ORD-12AAA3%'\").all();
console.log('Messages matching ORD-12AAA3:', JSON.stringify(msgs, null, 2));

// Check emails
const emails = db.prepare(\"SELECT * FROM ob_emails WHERE content LIKE '%ORD-12AAA3%' OR subject LIKE '%ORD-12AAA3%'\").all();
console.log('Emails matching ORD-12AAA3:', JSON.stringify(emails, null, 2));

// Check calendar events
const events = db.prepare(\"SELECT * FROM ob_calendar_events WHERE description LIKE '%ORD-12AAA3%' OR summary LIKE '%ORD-12AAA3%'\").all();
console.log('Calendar events matching ORD-12AAA3:', JSON.stringify(events, null, 2));

// Check orders table
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%ORD-12AAA3%'\").all();
console.log('Orders:', JSON.stringify(orders, null, 2));

db.close();
"
